package io.ahroni.dailytally;
import androidx.core.view.WindowCompat;import androidx.core.view.WindowInsetsCompat;import androidx.core.view.ViewCompat;import androidx.core.view.WindowInsetsControllerCompat;import androidx.core.graphics.Insets;import android.database.Cursor;import android.provider.ContactsContract;import org.json.JSONObject;import org.json.JSONArray;import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.provider.MediaStore;import android.print.PrintManager;import android.webkit.*;import android.view.*;import android.widget.*;import androidx.core.content.FileProvider;import java.io.*;
public class MainActivity extends androidx.fragment.app.FragmentActivity {
 private android.window.OnBackInvokedCallback backCallback;private WebView web;private ValueCallback<Uri[]> files;private Uri cameraUri;private byte[] pendingExport;private static final int PICK=10,SAVE=11,CONTACT=12;private String contactRequest;
 private boolean trusted(String value){try{Uri a=Uri.parse(BuildConfig.APP_URL),b=Uri.parse(value);return "https".equals(b.getScheme())&&a.getHost().equals(b.getHost())&&(b.getPort()==-1||b.getPort()==443);}catch(Exception e){return false;}}
 private void external(String url){try{Uri uri=Uri.parse(url);String s=uri.getScheme();if("https".equals(s)||"mailto".equals(s)||"tel".equals(s))startActivity(new Intent(Intent.ACTION_VIEW,uri));}catch(Exception ignored){Toast.makeText(this,"No app is available to open this link.",Toast.LENGTH_SHORT).show();}}
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setSoftInputMode(Build.VERSION.SDK_INT>=30?WindowManager.LayoutParams.SOFT_INPUT_ADJUST_NOTHING:WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);WindowCompat.setDecorFitsSystemWindows(getWindow(),false);if(Build.VERSION.SDK_INT<35){getWindow().setStatusBarColor(android.graphics.Color.TRANSPARENT);getWindow().setNavigationBarColor(android.graphics.Color.TRANSPARENT);}FrameLayout root=new FrameLayout(this);root.setBackgroundColor(android.graphics.Color.rgb(16,75,61));web=new WebView(this);root.addView(web,new FrameLayout.LayoutParams(-1,-1));setContentView(root);ViewCompat.setOnApplyWindowInsetsListener(root,(view,insets)->{Insets bars=insets.getInsets(WindowInsetsCompat.Type.systemBars()|WindowInsetsCompat.Type.displayCutout());Insets keyboard=insets.getInsets(WindowInsetsCompat.Type.ime());int bottom=Build.VERSION.SDK_INT>=30?Math.max(bars.bottom,keyboard.bottom):bars.bottom;if(view.getPaddingLeft()!=bars.left||view.getPaddingTop()!=bars.top||view.getPaddingRight()!=bars.right||view.getPaddingBottom()!=bottom)view.setPadding(bars.left,bars.top,bars.right,bottom);return WindowInsetsCompat.CONSUMED;});ViewCompat.requestApplyInsets(root);WindowInsetsControllerCompat controller=new WindowInsetsControllerCompat(getWindow(),root);controller.setAppearanceLightStatusBars(false);controller.setAppearanceLightNavigationBars(false);if(Build.VERSION.SDK_INT>=33){backCallback=()->handleAppBack();getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,backCallback);}WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(true);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);CookieManager.getInstance().setAcceptCookie(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);web.addJavascriptInterface(new Exports(),"DailyTallyFiles");
 web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){String url=request.getUrl().toString();if(trusted(url))return false;external(url);return true;}@Override public void onReceivedError(WebView view,WebResourceRequest request,WebResourceError error){if(request.isForMainFrame())new AlertDialog.Builder(MainActivity.this).setTitle("Unable to connect").setMessage("Check your internet connection. The server may take a little time to start.").setPositiveButton("Retry",(d,w)->web.loadUrl(BuildConfig.APP_URL)).setNegativeButton("Close",(d,w)->finish()).show();}@Override public void onPageFinished(WebView view,String url){CookieManager.getInstance().flush();if(!trusted(url))return;view.evaluateJavascript("(()=>{if(window.__dailyNative)return;window.__dailyNative=true;window.print=()=>DailyTallyFiles.printPage();document.addEventListener('click',e=>{const a=e.target.closest('a[download]');if(!a||!a.href.startsWith('blob:'))return;e.preventDefault();fetch(a.href).then(r=>r.blob()).then(blob=>{const reader=new FileReader();reader.onload=()=>DailyTallyFiles.saveFile(a.download||'DailyTally-report.csv',blob.type||'text/plain',reader.result.split(',')[1]);reader.readAsDataURL(blob)}).catch(()=>alert('Unable to save the file. Try again.'))},true)})()",null);}});
 web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView view,ValueCallback<Uri[]> callback,FileChooserParams params){if(files!=null)files.onReceiveValue(null);files=callback;cameraUri=null;Intent content=params.createIntent();content.addCategory(Intent.CATEGORY_OPENABLE);Intent chooser=Intent.createChooser(content,"Choose a photo or file");try{File folder=new File(getCacheDir(),"capture");folder.mkdirs();File file=File.createTempFile("photo-",".jpg",folder);cameraUri=FileProvider.getUriForFile(MainActivity.this,getPackageName()+".files",file);Intent camera=new Intent(MediaStore.ACTION_IMAGE_CAPTURE);camera.putExtra(MediaStore.EXTRA_OUTPUT,cameraUri);camera.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);chooser.putExtra(Intent.EXTRA_INITIAL_INTENTS,new Intent[]{camera});}catch(Exception ignored){}try{startActivityForResult(chooser,PICK);}catch(Exception e){files.onReceiveValue(null);files=null;}return true;}});
 if(state==null)web.loadUrl(BuildConfig.APP_URL);else web.restoreState(state);
 }
 private void sendContactResult(String requestId,JSONObject payload){if(web==null||!trusted(web.getUrl()))return;web.evaluateJavascript("window.DailyTallyContacts&&window.DailyTallyContacts.receive("+JSONObject.quote(requestId)+","+payload.toString()+")",null);}
 private void contactError(String requestId){try{sendContactResult(requestId,new JSONObject().put("error",true));}catch(Exception ignored){}}
 private void openContactPicker(String requestId){if(!trusted(web.getUrl())||requestId==null||!requestId.matches("[A-Za-z0-9_-]{1,100}"))return;if(contactRequest!=null){contactError(requestId);return;}contactRequest=requestId;try{Intent intent=new Intent(Intent.ACTION_PICK);intent.setDataAndType(ContactsContract.CommonDataKinds.Phone.CONTENT_URI,ContactsContract.CommonDataKinds.Phone.CONTENT_TYPE);startActivityForResult(intent,CONTACT);}catch(Exception error){contactRequest=null;contactError(requestId);}}
 private void receiveContactResult(int result,Intent data){String requestId=contactRequest;contactRequest=null;if(requestId==null)return;try{if(result!=RESULT_OK){sendContactResult(requestId,new JSONObject().put("cancelled",true));return;}Uri selected=data==null?null:data.getData();if(selected==null||!"content".equals(selected.getScheme()))throw new IllegalArgumentException();String[] columns={ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME,ContactsContract.CommonDataKinds.Phone.NUMBER};try(Cursor cursor=getContentResolver().query(selected,columns,null,null,null)){if(cursor==null||!cursor.moveToFirst())throw new IllegalArgumentException();String name=cursor.getString(cursor.getColumnIndexOrThrow(columns[0])),number=cursor.getString(cursor.getColumnIndexOrThrow(columns[1]));if(number==null||number.trim().isEmpty())throw new IllegalArgumentException();JSONObject contact=new JSONObject().put("name",new JSONArray().put(name==null||name.trim().isEmpty()?number:name)).put("tel",new JSONArray().put(number));sendContactResult(requestId,new JSONObject().put("contact",contact));}}catch(Exception error){contactError(requestId);}}
 private boolean authBusy=false;
 private void authResult(String id,JSONObject result){authBusy=false;sendAuthResponse(id,result);}
 private void sendAuthResponse(String id,JSONObject result){if(web!=null&&trusted(web.getUrl()))web.evaluateJavascript("window.DailyTallyNativeAuth&&window.DailyTallyNativeAuth.receive("+JSONObject.quote(id)+","+result.toString()+")",null);}
 private boolean authRequest(String id){return trusted(web.getUrl())&&id!=null&&id.matches("[A-Za-z0-9_-]{1,100}");}
 public class Exports {
 @JavascriptInterface public void nativeAuth(String requestId,String operation,String encoded){runOnUiThread(()->{if(!authRequest(requestId))return;try{JSONObject input=new JSONObject(encoded);if(operation.equals("available")){sendAuthResponse(requestId,new JSONObject().put("available",DeviceAuthenticator.available(MainActivity.this)));return;}if(authBusy){sendAuthResponse(requestId,new JSONObject().put("error","Finish the current verification first."));return;}authBusy=true;if(operation.equals("google")){GoogleAuthenticator.signIn(MainActivity.this,input.getString("clientId"),input.getString("challenge"),result->authResult(requestId,result));}else if(operation.equals("register")||operation.equals("login")){DeviceAuthenticator.authenticate(MainActivity.this,input.getString("keyId"),input.getString("challenge"),operation.equals("register"),result->authResult(requestId,result));}else if(operation.equals("remove")){DeviceAuthenticator.remove(input.getString("keyId"));authResult(requestId,new JSONObject().put("ok",true));}else throw new IllegalArgumentException();}catch(Exception error){try{authResult(requestId,new JSONObject().put("error","Device verification failed. Please try again."));}catch(Exception ignored){}}});}
@JavascriptInterface public void openSms(String phone,String message){runOnUiThread(()->{if(!trusted(web.getUrl())||phone==null||!phone.matches("\\+?[0-9]{7,15}")||message==null||message.length()>10000)return;try{Intent intent=new Intent(Intent.ACTION_SENDTO,Uri.parse("smsto:"+phone));intent.putExtra("sms_body",message);startActivity(intent);}catch(Exception error){Toast.makeText(MainActivity.this,"No messaging app is available.",Toast.LENGTH_LONG).show();}});}@JavascriptInterface public void pickContact(String requestId){runOnUiThread(()->openContactPicker(requestId));}@JavascriptInterface public void exitApp(){runOnUiThread(()->{if(trusted(web.getUrl()))finish();});}@JavascriptInterface public void printPage(){runOnUiThread(()->{if(!trusted(web.getUrl()))return;PrintManager manager=(PrintManager)getSystemService(PRINT_SERVICE);manager.print("DailyTally report",web.createPrintDocumentAdapter("DailyTally"),null);});}@JavascriptInterface public void saveFile(String filename,String mime,String encoded){if(encoded==null||encoded.length()>30000000)return;runOnUiThread(()->{if(!trusted(web.getUrl())||pendingExport!=null)return;try{pendingExport=android.util.Base64.decode(encoded,android.util.Base64.DEFAULT);String name=new File(filename).getName();if(name.length()>100)name="DailyTally-export.txt";Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType(mime.startsWith("text/")||mime.equals("application/json")?mime:"application/octet-stream");intent.putExtra(Intent.EXTRA_TITLE,name);startActivityForResult(intent,SAVE);}catch(Exception e){pendingExport=null;}});}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==CONTACT){receiveContactResult(result,data);return;}if(request==PICK&&files!=null){Uri[] selected=result==RESULT_OK?WebChromeClient.FileChooserParams.parseResult(result,data):null;if(result==RESULT_OK&&(selected==null||selected.length==0)&&cameraUri!=null)selected=new Uri[]{cameraUri};files.onReceiveValue(selected);files=null;cameraUri=null;}if(request==SAVE){try{if(result==RESULT_OK&&data!=null&&pendingExport!=null){try(OutputStream output=getContentResolver().openOutputStream(data.getData())){output.write(pendingExport);}}}catch(Exception e){Toast.makeText(this,"The file could not be saved.",Toast.LENGTH_LONG).show();}finally{pendingExport=null;}}}
 @Override public void onBackPressed(){handleAppBack();}
 private void handleAppBack(){WindowInsetsCompat insets=ViewCompat.getRootWindowInsets(web);if(insets!=null&&insets.isVisible(WindowInsetsCompat.Type.ime())){new WindowInsetsControllerCompat(getWindow(),web).hide(WindowInsetsCompat.Type.ime());return;}if(web==null||!trusted(web.getUrl())){showExitFallback();return;}web.evaluateJavascript("(()=>{if(window.DailyTallyNavigation)return window.DailyTallyNavigation.back();const dialog=document.querySelector('dialog[open]');if(dialog){dialog.close();return 'handled'}return 'exit'})()",result->{if(!"\"handled\"".equals(result))showExitFallback();});}
 private void showExitFallback(){new AlertDialog.Builder(this).setTitle("Exit DailyTally?").setMessage("Do you want to exit? You can return anytime.").setNegativeButton("No, stay",(dialog,which)->dialog.dismiss()).setPositiveButton("Yes, exit",(dialog,which)->finish()).show();}
 @Override protected void onDestroy(){if(Build.VERSION.SDK_INT>=33&&backCallback!=null)getOnBackInvokedDispatcher().unregisterOnBackInvokedCallback(backCallback);super.onDestroy();}
 @Override protected void onSaveInstanceState(Bundle state){web.saveState(state);super.onSaveInstanceState(state);}
}
